package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen1Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(83L, result);
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        byte[] buffer = "   0755".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 7);
        assertEquals(493L, result);
    }

    @Test
    public void testParseOctal_WithTrailingSpacesAndNulls() {
        // Testing trailing space and trailing NUL (0)
        byte[] buffer = "0123   \0\0".getBytes();
        // Note: '0' is 48, ' ' is 32, '\0' is 0
        // We manually construct the buffer to ensure NUL bytes are present
        byte[] complexBuffer = new byte[10];
        System.arraycopy("0123".getBytes(), 0, complexBuffer, 0, 4);
        complexBuffer[4] = ' ';
        complexBuffer[5] = ' ';
        complexBuffer[6] = 0;
        complexBuffer[7] = 0;
        complexBuffer[8] = 0;
        complexBuffer[9] = 0;

        long result = TarUtils.parseOctal(complexBuffer, 0, 10);
        assertEquals(83L, result);
    }

    @Test
    public void testParseOctal_BufferStartsAtZero() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        buffer[1] = '1';
        buffer[2] = '2';
        // length must be >= 2
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "1".getBytes();
        TarUtils.parseOctal(buffer, 0, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidDigit() {
        byte[] buffer = "0128".getBytes(); // '8' is invalid octal
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_InvalidChar() {
        byte[] buffer = "012A".getBytes(); // 'A' is invalid
        TarUtils.parseOctal(buffer, 0, 4);
    }

    @Test
    public void testParseOctal_OffsetTest() {
        byte[] buffer = "abc 077".getBytes();
        // offset 4 is the space, length 4 covers " 077"
        long result = TarUtils.parseOctal(buffer, 3, 4);
        assertEquals(63L, result);
    }

    @Test
    public void testParseOctal_AllSpacesOrNulls() {
        // If the loop trims everything, result should remain 0
        byte[] buffer = "  \0  ".getBytes();
        // length 5
        long result = TarUtils.parseOctal(buffer, 0, 5);
        assertEquals(0L, result);
    }

    @Test
    public void testParseOctal_LargeOctal() {
        // Testing large value to ensure long handles it
        // 777777777777 (octal)
        byte[] buffer = "777777777777".getBytes();
        long result = TarUtils.parseOctal(buffer, 0, 12);
        // 7 * (8^11 + 8^10 ... + 8^0)
        long expected = 0;
        for (int i = 0; i < 12; i++) {
            expected = (expected << 3) + 7;
        }
        assertEquals(expected, result);
    }
}
